--
--
-- -> Arquivo de hotfix para a estrutura de tabelas do Geoserver
-- -> Autor: Victor Arantes
-- -> Data: 2026-07-03
-- -> Descrição: Este arquivo contém alterações na estrutura do banco de dados do Geoserver, 
--recriando as tabelas, views e índices GeoCron + Litoestratigrafia, criando as tables com o parâmetro "GENERATED BY DEFAULT" na pkey (if).
-- -> Este arquivo corrige o bug onde o airflow não consegue realizar a inserção dos dados por constraint de chave primária nula (?).
-- -> OBSERVAÇÃO 1: É melhor executar este patch tendo certeza de que as fontes estão online, pois se não a camada ficará sem dados até
--que o airflow consiga consumir a fonte.
-- -> OBSERVAÇÃO 2: Observou-se que a versão do GDAL (3.2.2 - 03/2021) utilizada na imagem do airflow não faz os 'handlings' para
--os inserts. A versão testada localmente (3.7.2 - 09/2023) já possui essa feature, não sendo necessário este hotfix.
--
--

---------------------DROPS
drop table if exists cprm.cprm_geocron cascade ;
DROP TABLE if exists cprm.cprm_lev_litostrat_100000 cascade;
drop table if exists cprm.cprm_lev_litostrat_25000 cascade ;
DROP TABLE if exists cprm.cprm_lev_litostrat_50000 cascade;
DROP TABLE if exists cprm.cprm_lev_litostrat_250000 cascade;
--------------------------


---------------------CREATES

CREATE TABLE cprm.cprm_geocron (
    id int2 GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    geom public.geometry(point, 4674) NULL,
    amostra varchar NULL,
    toponomia varchar NULL,
    rocha varchar NULL,
    mtd_geoposi varchar NULL,
    erro_localc varchar NULL,
    mtds varchar NULL,
    mat_analisados varchar NULL,
    nivel_acesso varchar NULL

);
CREATE INDEX cprm_geocron_idx ON cprm.cprm_geocron USING gist (geom);
CREATE INDEX idx_cprm_cprm_geocron ON cprm.cprm_geocron USING btree (id);

--

CREATE TABLE cprm.cprm_lev_litostrat_25000 (
	id int2 GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	geom public.geometry(multipolygon, 4674) NULL,
	id_uni_estratigrafica int2 NULL,
	sigla varchar NULL,
	hierarquia varchar NULL,
	nome varchar NULL,
	amb_tecto varchar NULL,
	sub_amb_tectonico varchar NULL,
	sigla_pai varchar NULL,
	nome_pai varchar NULL,
	legenda varchar NULL,
	escala varchar NULL,
	mapa varchar NULL,
	litotipos varchar NULL,
	"range" varchar NULL,
	idade_min int2 NULL,
	idade_max int2 NULL,
	eon_min varchar NULL,
	eon_max varchar NULL,
	era_min varchar NULL,
	era_max varchar NULL,
	sistema_min varchar NULL,
	sistema_max varchar NULL,
	epoca_min varchar NULL,
	epoca_max varchar NULL,
	siglas_historicas varchar NULL,
	grupo varchar NULL
	
);
CREATE INDEX cprm_lev_litostrat_25000_idx ON cprm.cprm_lev_litostrat_25000 USING gist (geom);
CREATE INDEX idx_cprm_cprm_lev_litostrat_25000 ON cprm.cprm_lev_litostrat_25000 using btree (id);

--

