	era_min varchar NULL,
	era_max varchar NULL,
	sistema_min varchar NULL,
	sistema_max varchar NULL,
	epoca_min varchar NULL,
	epoca_max varchar NULL,
	siglas_historicas varchar NULL,
	grupo varchar NULL
	
);
CREATE INDEX cprm_lev_litostrat_50000_idx ON cprm.cprm_lev_litostrat_50000 USING gist (geom);
