CREATE TABLE cprm.cprm_lev_litostrat_100000 (
	id int4 GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	geom public.geometry(multipolygon, 4674) NULL,
	id_uni_estratigrafica int2 NULL,
	sigla varchar(180) NULL,
	hierarquia varchar(180) NULL,
	nome varchar(254) NULL,
	amb_tecto varchar(180) NULL,
	sub_amb_tectonico varchar(180) NULL,
	sigla_pai varchar(180) NULL,
	nome_pai varchar(254) NULL,
	legenda varchar(254) NULL,
	escala varchar(14) NULL,
	mapa varchar(254) NULL,
	litotipos varchar(254) NULL,
	"range" varchar(50) NULL,
	idade_min int2 NULL,
	idade_max int2 NULL,
	eon_min varchar(180) NULL,
	eon_max varchar(180) NULL,
	era_min varchar(180) NULL,
	era_max varchar(180) NULL,
	sistema_min varchar(180) NULL,
	sistema_ma varchar(180) NULL,
	epoca_min varchar(180) NULL,
	epoca_max varchar(180) NULL,
	siglas_historicas varchar(254) NULL
	
);
CREATE INDEX cprm_lev_litostrat_geom_gist ON cprm.cprm_lev_litostrat_100000 USING gist (geom);
CREATE INDEX idx_cprm_cprm_lev_litostrat_100000 ON cprm.cprm_lev_litostrat_100000 using btree (id);

--

CREATE TABLE cprm.cprm_lev_litostrat_250000 (
	id int4 GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	geom public.geometry(multipolygon, 4674) NULL,
	fid int2 NULL,
	id_uni_estratigrafica int2 NULL,
	sigla varchar NULL,
	nome varchar NULL,
	amb_tecto varchar NULL,
	sub_amb_tectonico varchar NULL,
	sigla_pai varchar NULL,
	nome_pai varchar NULL,
	legenda varchar NULL,
	escala varchar NULL,
	mapa varchar NULL,
	litotipos varchar NULL,
	idade_min int2 NULL,
	idade_max int2 NULL,
	eon_min varchar NULL,
	eon_max varchar NULL,
	era_min varchar NULL,
	era_max varchar NULL,
	sistema_min varchar NULL,
	sistema_max varchar NULL,
	epoca_min varchar NULL,
	epoca_max varchar NULL,
	siglas_historicas varchar NULL,
	grupo varchar NULL,
	shp_area numeric(13, 10) NULL,
	shp_length numeric(13, 10) NULL,
	objectid int8 NULL,
	hierarquia varchar NULL,
	"range" varchar NULL
	
);
CREATE INDEX cprm_lev_litostrat_250000_idx ON cprm.cprm_lev_litostrat_250000 USING gist (geom);
CREATE INDEX idx_cprm_cprm_lev_litostrat_250000 ON cprm.cprm_lev_litostrat_250000 USING btree (id);

---------------------------VIEWS 

CREATE OR REPLACE VIEW geoserver.vw_cprm_geocron
AS SELECT cprm_geocron.id,
    cprm_geocron.geom,
    cprm_geocron.amostra,
    cprm_geocron.toponomia,
    cprm_geocron.rocha,
    cprm_geocron.mtd_geoposi,
    cprm_geocron.erro_localc,
    cprm_geocron.mtds,
    cprm_geocron.mat_analisados,
    cprm_geocron.nivel_acesso
   FROM cprm.cprm_geocron;

